import * as T from './three.module.js';
import {readableSign} from './race-shot.js?v=track8';
// Presentation distances are separate from the authoritative timed result.
export function runout(age,speed=17){const duration=13,t=Math.min(duration,Math.max(0,age)),v=Math.max(10,Math.min(23,speed)),a=1-t/duration;return {distance:v*duration/3*(1-a*a*a),speed:v*a*a};}
export function paradePosition(time,index=0){const a=time*.105-index*Math.PI/3,x=30+Math.sin(a)*17,z=1+Math.cos(a)*9;return {position:new T.Vector3(x,.2,z),yaw:Math.atan2(Math.cos(a)*17,-Math.sin(a)*9)};}
// Repeatable, high resolution material detail; no fetched or unlicensed art.
export function detailTexture(kind,size=512){const bytes=new Uint8Array(size*size*4);for(let y=0;y<size;y++)for(let x=0;x<size;x++){const n=(Math.sin(x*127.1+y*311.7)*43758.5453)%1,f=Math.abs(n),grain=kind==='wood'?Math.sin(x*.1+Math.sin(y*.015)*3)*.08+Math.sin(x*.55+y*.007)*.025:kind==='silk'?Math.sin(x*Math.PI)*.02+Math.sin(y*1.57)*.03:kind==='coat'?Math.sin(x*.8+y*.055)*.06:kind==='sand'?Math.sin(y*.5)*.035:0;const c=Math.max(0,Math.min(255,Math.round(224+f*28+grain*255)));const i=(y*size+x)*4;bytes[i]=bytes[i+1]=bytes[i+2]=c;bytes[i+3]=255;}const t=new T.DataTexture(bytes,size,size,T.RGBAFormat);t.wrapS=t.wrapT=T.RepeatWrapping;t.magFilter=T.LinearFilter;t.minFilter=T.LinearMipmapLinearFilter;t.generateMipmaps=true;t.needsUpdate=true;return t;}
export function addRaceDayVenue(scene,sample,mobile){
 const group=new T.Group();group.name='Race day paddock and hospitality';scene.add(group);const mats=new Map();function mat(c){if(!mats.has(c))mats.set(c,new T.MeshStandardMaterial({color:c,roughness:.64}));return mats.get(c);}
 function box(c,x,y,z,w,h,d){const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat(c));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;group.add(m);return m;}
 function tube(points,c,r=.035){const m=new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(points),points.length*4,r,6,false),mat(c));m.castShadow=true;group.add(m);return m;}
 const oval=(rx,rz,y)=>Array.from({length:81},(_,i)=>new T.Vector3(30+Math.sin(i/80*Math.PI*2)*rx,y,1+Math.cos(i/80*Math.PI*2)*rz));
 // Walking ring with a clear sand surface, white top rail and planted centre.
 const pos=[],ix=[];for(let i=0;i<=128;i++){const a=i/128*Math.PI*2;for(const side of [-1,1])pos.push(30+Math.sin(a)*(17+side*2.3),.13,1+Math.cos(a)*(9+side*2.3));if(i<128){let k=i*2;ix.push(k,k+1,k+2,k+1,k+3,k+2);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(pos,3));g.setIndex(ix);g.computeVertexNormals();const ring=new T.Mesh(g,new T.MeshStandardMaterial({color:'#d8b997',roughness:1,side:T.DoubleSide}));ring.receiveShadow=true;group.add(ring);
 for(const [rx,rz]of [[13.9,5.9],[20.1,12.1]]){tube(oval(rx,rz,1.0),'#f2eee1',.055);tube(oval(rx,rz,.55),'#eee8d5',.035);for(let i=0;i<40;i++){const a=i/40*Math.PI*2;box('#f3eedd',30+Math.sin(a)*rx,.53,1+Math.cos(a)*rz,.095,1.08,.095);}}
 // Clipped hedges with leaves rather than smooth placeholder blobs.
 const hedge=new T.InstancedMesh(new T.IcosahedronGeometry(.22,1),mat('#4d7249'),1000),d=new T.Object3D();for(let i=0;i<1000;i++){const a=i*.618033*Math.PI*2;d.position.set(30+Math.sin(a)*(12.3+Math.sin(i*13)*.7),.35+(i%5)*.12,1+Math.cos(a)*(4.5+Math.cos(i*7)*.7));d.rotation.set(i,i*2,i*.3);d.scale.setScalar(.75+(i%4)*.15);d.updateMatrix();hedge.setMatrixAt(i,d.matrix);}hedge.castShadow=true;group.add(hedge);
 function sign(text,x,y,z,w=8,h=1.5){const c=document.createElement('canvas');c.width=1024;c.height=256;const ctx=c.getContext('2d');ctx.fillStyle='#143b37';ctx.fillRect(0,0,1024,256);ctx.fillStyle='#edce8b';ctx.font='600 66px serif';ctx.textAlign='center';ctx.fillText(text,512,150);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;const mesh=readableSign(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:tex,side:T.FrontSide}));mesh.position.set(x,y,z);group.add(mesh);return mesh;}
 sign('THE PARADE RING',30,2.1,15,11,1.5);for(const x of [24,36])box('#bba778',x,1,15,.12,2,.12);
 // Hospitality pavilions with peaked fabric roofs, trim, tables and flower boxes.
 for(let i=0;i<4;i++){const x=-37+i*15,z=-25;box('#eee3cb',x,1.6,z,11,3.2,7);box('#294f48',x,3.4,z,11.7,.22,7.6);const roof=new T.Mesh(new T.ConeGeometry(8.1,3.2,4),mat(i%2?'#e9d4ae':'#ece7da'));roof.rotation.y=Math.PI/4;roof.scale.z=.7;roof.position.set(x,5.1,z);roof.castShadow=true;group.add(roof);for(let j=0;j<3;j++){box('#354b49',x+(j-1)*3.2,1.8,z+3.53,2.5,2.1,.08);box('#c6a773',x+(j-1)*3.2,.7,z+3.7,2.7,.4,.5);}sign(['PADDOCK CLUB','MEADOW PARK','RACE OFFICE','THE OWNERS CLUB'][i],x,3.2,z+3.65,9,.9);}
 // Brass trophy on the infield presentation dais.
 box('#e6d6b3',-7,.35,7,9,.7,5);box('#294d49',-7,.8,7,2,.3,1.4);const gold=new T.MeshStandardMaterial({color:'#dba849',metalness:.78,roughness:.25});const cup=new T.Mesh(new T.LatheGeometry([new T.Vector2(.3,0),new T.Vector2(.3,.12),new T.Vector2(.12,.2),new T.Vector2(.12,.65),new T.Vector2(.48,.85),new T.Vector2(.62,1.4),new T.Vector2(.6,1.48)],32),gold);cup.position.set(-7,1,7);cup.castShadow=true;group.add(cup);for(const side of [-1,1]){const handle=new T.Mesh(new T.TorusGeometry(.32,.045,8,24),gold);handle.position.set(-7+side*.54,2,7);group.add(handle);}
 // Turf blades are instanced: detailed close to camera without thousands of draws.
 const bladeGeometry=new T.BufferGeometry();bladeGeometry.setAttribute('position',new T.Float32BufferAttribute([-.035,0,0,.035,0,0,.012,.16,0,0,0,-.035,0,0,.035,0,.13,.01],3));bladeGeometry.computeVertexNormals();
 const count=mobile?1400:5000,blades=new T.InstancedMesh(bladeGeometry,new T.MeshStandardMaterial({color:'#739151',side:T.DoubleSide,roughness:1}),count);for(let i=0;i<count;i++){const x=Math.sin(i*73.132)*73,z=Math.cos(i*37.37)*28;if((x-30)**2/22**2+(z-1)**2/14**2<1||z<-18||x<-6&&x>-52&&z<13){d.scale.setScalar(0);}else d.scale.set(1,.45+(i%7)*.07,1);d.position.set(x,.21,z);d.rotation.set(0,i*2.4,0);d.updateMatrix();blades.setMatrixAt(i,d.matrix);}blades.name='Tapered turf tufts';group.add(blades);
 // Layered tree crowns, branching trunks and individually lit foliage.
 const leafCount=mobile?1800:4200,leafGeo=new T.IcosahedronGeometry(.48,1),leafMat=new T.MeshStandardMaterial({color:'#afbd79',roughness:.9});const leaves=new T.InstancedMesh(leafGeo,leafMat,leafCount);leaves.castShadow=true;const bark=mat('#78634a');let li=0;
 for(let i=0;i<18;i++){const a=i/18*Math.PI*2,x=Math.sin(a)*114,z=Math.cos(a)*59;if(Math.abs(x)<80&&Math.abs(z)>45)continue;const trunk=new T.Mesh(new T.CylinderGeometry(.18,.34,4.5,9),bark);trunk.position.set(x,2.25,z);trunk.castShadow=true;group.add(trunk);for(let branch=0;branch<3;branch++){const tip=new T.Vector3(x+Math.sin(branch*2.1+i)*2.4,5.7+(branch%2),z+Math.cos(branch*2.1+i)*2.1);tube([new T.Vector3(x,2.5,z),new T.Vector3(x,4,z),tip],'#78634a',.12);for(let j=0;j<(mobile?65:145)&&li<leafCount;j++){const t=j*2.399,rad=Math.sqrt(j/(mobile?65:145))*2;d.position.copy(tip).add(new T.Vector3(Math.cos(t)*rad,Math.sin(j*8.13)*1.3,Math.sin(t)*rad));d.rotation.set(i+j,j*3.1,j*.8);d.scale.set(1+(j%3)*.2,.55,1);d.updateMatrix();leaves.setMatrixAt(li,d.matrix);leaves.setColorAt(li,new T.Color(['#7e9a5e','#b1bb79','#8ca66c','#d3ba8c'][j%4]));li++;}}}leaves.count=li;group.add(leaves);
 // Finish photo tower and gold distance-marker boards.
 box('#263d43',-4,3.1,61,2,6.2,2);box('#efe7d2',-4,6.4,61,3.3,.35,3);box('#314951',-4,7.1,61,2.8,1.2,2.5);sign('PHOTO FINISH',-4,5,59.94,3,.7);
 for(let i=1;i<=3;i++){const s=sample(i/4,7.5),m=sign(String(400-i*100)+' m',s.p.x,2.1,s.p.z,2.5,1.4);m.rotation.y=Math.atan2(s.dir.x,s.dir.z)+Math.PI/2;box('#d9d7bb',s.p.x,1,s.p.z,.1,2,.1);}
 return {group};
}
